import Link from "next/link";

type SideProject = {
  slug: string;
  title: string;
  sketch_image?: string | null;
};

function SideItem({
  project,
  side,
}: {
  project: SideProject;
  side: "left" | "right";
}) {
  return (
    <Link
      href={`/proyectos/${project.slug}`}
      className={`project-side-nav project-side-nav-${side}`}
      aria-label={side === "left" ? `Proyecto anterior: ${project.title}` : `Proyecto siguiente: ${project.title}`}
    >
      <span className="project-side-arrow">{side === "left" ? "‹" : "›"}</span>

      <span className="project-side-preview">
        {project.sketch_image && (
          <span className="project-side-thumb">
            <img src={project.sketch_image} alt="" />
          </span>
        )}

        <span className="project-side-copy">
          <strong>{project.title}</strong>
          <span>Ver proyecto</span>
        </span>
      </span>
    </Link>
  );
}

export default function ProjectSideNav({
  previous,
  next,
}: {
  previous?: SideProject | null;
  next?: SideProject | null;
}) {
  return (
    <>
      {previous && <SideItem project={previous} side="left" />}
      {next && <SideItem project={next} side="right" />}
    </>
  );
}
